{"code": "const script = String.raw`
src = open('tmp/sheaf/xif/paper/S1942PrePsiFiveActual.lean', encoding='utf-8').read()
idx = src.index('theorem S1942A_map')
head = src[:idx]
# close CommRing section and namespace, remove open section? We are inside section CommRing.
out = head + 'end CommRing\n\nend LeanFormal.IUT.XiFPaper.S1942PrePsiFiveActual\n'
open('tmp/_S1942_size.lean','w',encoding='utf-8').write(out)
print(len(out))
`;
await tools.write({ file_path: "D:\\lean\\tmp\\s1942_size.py", content: script });
let r = await tools.pwsh({ description: "Generate definitions-only file", command: "python -u tmp\\s1942_size.py", timeoutMs: 60000 });
console.log(r.stdout.text);
r = await tools.pwsh({ description: "Compile definitions-only olean", command: "lake env lean -j1 -R D:\\lean -o tmp\\_S1942_size.olean tmp\\_S1942_size.lean 2>&1 | Tee-Object -FilePath tmp\\_S1942_size.log; exit $LASTEXITCODE", timeoutMs: 600000 });
console.log(JSON.stringify(r).slice(0,300));
if (r.kind === "foreground") { console.log(r.stdout.text.slice(0,2000)); }
", "description": "Measure definitions-only olean size", "timeoutMs": 620000}

